import pandas as pd


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    """Case-insensitive / flexible lookup for input relations."""
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k, v in inputs.items():
        if k.lower() == lname:
            return v
    raise KeyError(name)


def _is_null(v):
    try:
        return pd.isna(v)
    except Exception:
        return v is None


def _is_change(a, b):
    """NULL-safe inequality: NULL vs NULL -> no change; NULL vs non-NULL -> change."""
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _tie_key(email, tier):
    """Build a NULL-safe sort key for lexicographic (email, tier) comparison.
    Treat NULL as sorting below any non-null value."""
    e_key = (0, "") if _is_null(email) else (1, email)
    t_key = (0, "") if _is_null(tier) else (1, tier)
    return (e_key, t_key)


def _pick_latest(group: pd.DataFrame) -> pd.Series:
    max_date = group["update_date"].max()
    candidates = group[group["update_date"] == max_date]
    if len(candidates) == 1:
        return candidates.iloc[0]

    best_row = None
    best_key = None
    for _, row in candidates.iterrows():
        k = _tie_key(row["email"], row["tier"])
        if best_key is None or k > best_key:
            best_key = k
            best_row = row
    return best_row


def run(inputs: dict) -> dict:
    dim_acct = _get_input(inputs, "DIM_ACCT").copy()
    stg_acct = _get_input(inputs, "STG_ACCT").copy()

    # ---------------------------------------------------------------
    # Step 1: Dedup STG_ACCT to latest per acct_id by update_date;
    # ties broken by greater (email, tier) lexicographic pair.
    # ---------------------------------------------------------------
    if len(stg_acct) == 0:
        dedup_rows = stg_acct
    else:
        picked = []
        for acct_id, group in stg_acct.groupby("acct_id", sort=False):
            picked.append(_pick_latest(group))
        dedup_rows = pd.DataFrame(picked).reset_index(drop=True)

    # ---------------------------------------------------------------
    # Working state: list of dict rows mirroring DIM_ACCT structure.
    # ---------------------------------------------------------------
    records = dim_acct.to_dict("records")

    for _, s in dedup_rows.iterrows():
        acct_id = s["acct_id"]
        email_s = s["email"]
        tier_s = s["tier"]
        update_date = s["update_date"]

        # locate current row for this acct_id (is_current == 1)
        cur_idx = None
        for i, r in enumerate(records):
            if r.get("acct_id") == acct_id and r.get("is_current") == 1:
                cur_idx = i
                break

        if cur_idx is None:
            # No current row -> insert new current version
            records.append(
                {
                    "acct_id": acct_id,
                    "email": email_s,
                    "tier": tier_s,
                    "eff_start_date": update_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
            )
            continue

        c = records[cur_idx]
        tier_changed = _is_change(c.get("tier"), tier_s)
        email_changed = _is_change(c.get("email"), email_s)

        if tier_changed:
            # expire current, insert new current version (TYPE-2)
            records[cur_idx]["eff_end_date"] = update_date
            records[cur_idx]["is_current"] = 0
            records.append(
                {
                    "acct_id": acct_id,
                    "email": email_s,
                    "tier": tier_s,
                    "eff_start_date": update_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
            )

        if email_changed:
            # retro-overwrite email across ALL rows (history + current) (TYPE-1)
            for r in records:
                if r.get("acct_id") == acct_id:
                    r["email"] = email_s

    dim_acct_out = pd.DataFrame(
        records,
        columns=[
            "acct_id",
            "email",
            "tier",
            "eff_start_date",
            "eff_end_date",
            "is_current",
        ],
    )

    return {"dim_acct_out": dim_acct_out}
